class RedisEventManager {
public:
    RedisEventManager(const char* hostname) {
        context = redisConnect(hostname, 6379);
        if (context == nullptr || context->err) {
            if (context) {
                std::cerr << "Error connecting to Redis: " << context->errstr << std::endl;
                redisFree(context);
            } else {
                std::cerr << "Failed to allocate Redis context" << std::endl;
            }
            // Handle connection failure gracefully
        }
    }

    void publishEvent(const std::string& eventName, const std::string& eventData) {
        redisReply* reply = (redisReply*)redisCommand(context, "PUBLISH %s %s", eventName.c_str(), eventData.c_str());
        if (reply == nullptr) {
            std::cerr << "Failed to publish event to Redis" << std::endl;
            // Handle publish failure gracefully
        } else {
            freeReplyObject(reply);
        }
    }

    void subscribeToEvent(const std::string& eventName, std::function<void(const std::string&)> callback) {
        redisReply* reply = (redisReply*)redisCommand(context, "SUBSCRIBE %s", eventName.c_str());
        if (reply == nullptr) {
            std::cerr << "Failed to subscribe to event from Redis" << std::endl;
            // Handle subscribe failure gracefully
        } else {
            freeReplyObject(reply);
            while (redisGetReply(context, (void**)&reply) == REDIS_OK) {
                if (reply->element[2] != nullptr && reply->element[2]->str != nullptr) {
                    callback(reply->element[2]->str);
                }
                freeReplyObject(reply);
            }
        }
    }

    ~RedisEventManager() {
        if (context != nullptr) {
            redisFree(context);
        }
    }

private:
    redisContext* context;
};

// Example usage
int main() {
    RedisEventManager eventManager("localhost");
    eventManager.publishEvent("test_event", "Test data");

    eventManager.subscribeToEvent("test_event", [](const std::string& eventData) {
        std::cout << "Received event data: " << eventData << std::endl;
    });

    // Keep the program running to receive subscription events
    while (true) {
        // Do other work or sleep
    }

    return 0;
}
