    public:
        DirectionalLight(const glm::vec3& direction, const glm::vec3& color)
            : direction_(direction), color_(color) {}

        virtual glm::vec3 CalculateIllumination(const glm::vec3& point) const override {
            return color_ * std::max(glm::dot(glm::vec3(0, 0, 1), -direction_), 0.0f);
        }

    private:
        glm::vec3 direction_;
        glm::vec3 color_;
    };

