#include <cmath>

double calculateGradientNorm(double sumx, double sumy, double sumz, bool normalize) {
    double gradientNorm = sqrt(sumx * sumx + sumy * sumy + sumz * sumz);
    if (normalize) {
        if (gradientNorm != 0) {
            sumx /= gradientNorm;
            sumy /= gradientNorm;
            sumz /= gradientNorm;
            gradientNorm = 1.0;  // After normalization, the magnitude becomes 1
        }
    }
    return gradientNorm;
}
