#include <string>
#include <algorithm>

bool validatePattern(const std::string& pattern, const std::string& inputStr) {
    auto patternIt = pattern.begin();
    auto inputIt = inputStr.begin();

    while (patternIt != pattern.end() && inputIt != inputStr.end()) {
        if (*patternIt == 'D') {
            if (!std::isdigit(*inputIt)) {
                return false;
            }
        } else if (*patternIt == 'S') {
            if (std::isdigit(*inputIt)) {
                return false;
            }
        } else {
            return false; // Invalid pattern character
        }
        ++patternIt;
        ++inputIt;
    }

    return patternIt == pattern.end() && inputIt == inputStr.end();
}
