[{"role": "assistant", "content": "```cpp
class ThreadSafeQueue {
private:
    std::mutex m_mutex;
    int m_queue[MAX_SIZE];
    int m_head, m_tail;

public:
    ThreadSafeQueue() : m_head(0), m_tail(0) {}

    int enqueue(int req) {
        std::lock_guard<std::mutex> lock(m_mutex);
        if ((m_tail + 1) % MAX_SIZE == m_head) {
            // Queue is full
            return -1;
        }
        m_queue[m_tail] = req;
        m_tail = (m_tail + 1) % MAX_SIZE;
        return 0;
    }

    int dequeue() {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (m_head == m_tail) {
            // Queue is empty
            return -1;
        }
        int item = m_queue[m_head];
        m_head = (m_head + 1) % MAX_SIZE;
        return item;
    }

    bool isEmpty() {
        std::lock_guard<std::mutex> lock(m_mutex);
        return m_head == m_tail;
    }
};
```
In the solution, the `enqueue` method checks if the queue is full before adding an element, the `dequeue` method checks if the queue is empty before removing an element, and the `isEmpty` method simply checks if the head and tail pointers are equal. All operations are protected by the mutex lock to ensure thread safety."}]

