// Function to count lines of code in a file
int countLinesOfCode(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return 0;
    }

    int lines = 0;
    std::string line;
    bool inBlockComment = false;

    while (std::getline(file, line)) {
        // Remove leading and trailing whitespace
        line = std::regex_replace(line, std::regex("^\\s+|\\s+$"), "");

        if (line.empty() || line.find("//") == 0 || inBlockComment) {
            continue;  // Skip empty lines, full-line comments, and lines within block comments
        }

        if (line.find("/*") != std::string::npos) {
            inBlockComment = true;  // Start of block comment
        }

        if (line.find("*/") != std::string::npos) {
            inBlockComment = false;  // End of block comment
            continue;
        }

        lines++;
    }

    file.close();
    return lines;
}

int main() {
    std::vector<std::string> filenames = {"file1.cpp", "file2.cpp"};  // Replace with actual file names

    int totalLines = 0;
    for (const auto& filename : filenames) {
        totalLines += countLinesOfCode(filename);
    }

    std::cout << "Total lines of code: " << totalLines << std::endl;

    return 0;
}
