template<int SZ> struct BCC {
    int N;
    vpi adj[SZ], ed;
    vi disc, low, par, art;
    vector<vector<int>> bcc;
    stack<int> stk;

    void addEdge(int u, int v) { 
        adj[u].pb({v,sz(ed)}), 
        adj[v].pb({u,sz(ed)}); 
        ed.pb({u,v});
    }

    void dfs(int u, int p, int &time) {
        disc[u] = low[u] = ++time;
        int children = 0;
        for (auto [v, id] : adj[u]) {
            if (!disc[v]) {
                children++;
                stk.push(id);
                par[v] = u;
                dfs(v, u, time);
                low[u] = min(low[u], low[v]);
                if ((p == -1 && children > 1) || (p != -1 && low[v] >= disc[u])) {
                    art[u] = 1;
                    vector<int> component;
                    while (true) {
                        int e = stk.top(); stk.pop();
                        component.push_back(e);
                        if (e == id) break;
                    }
                    bcc.push_back(component);
                }
            } else if (v != p && disc[v] < disc[u]) {
                low[u] = min(low[u], disc[v]);
                stk.push(id);
            }
        }
    }

    vector<vector<int>> findBiconnectedComponents() {
        disc.assign(N, 0);
        low.assign(N, 0);
        par.assign(N, -1);
        art.assign(N, 0);
        bcc.clear();
        int time = 0;
        for (int i = 0; i < N; i++) {
            if (!disc[i]) {
                dfs(i, -1, time);
                if (!stk.empty()) {
                    vector<int> component;
                    while (!stk.empty()) {
                        component.push_back(stk.top());
                        stk.pop();
                    }
                    bcc.push_back(component);
                }
            }
        }
        return bcc;
    }
};
```

