using namespace std;

void quick_sort(vector<int>& v, int start, int end) {
    if (start < end) {
        int pivot = v[end];
        int i = (start - 1);

        for(int j = start; j <= end - 1; j++) {
            if (v[j] < pivot) {
                i++;
                swap(v[i], v[j]);
            }
        }
        swap(v[i + 1], v[end]);
        int pi = (i + 1);

        quick_sort(v, start, pi - 1);
        quick_sort(v, pi + 1, end);
    }
}

vector<int> merged_list(vector<int>& list1, vector<int>& list2) {
    vector<int> nums;
    nums.reserve(list1.size() + list2.size());
    nums.insert(nums.end(), list1.begin(), list1.end());
    nums.insert(nums.end(), list2.begin(), list2.end());

    quick_sort(nums, 0, nums.size() - 1);

    set<int> s(nums.begin(), nums.end());
    nums.assign(s.begin(), s.end());

    reverse(nums.begin(), nums.end());

    return nums;
}
