    if (!head) return;

    Node<T> *temp = head;
    while (temp) {
        if (temp->value == value) {
            // If node to be deleted is head node 
            if (head == temp)
                head = temp->next;

            // Change next and prev only if they are not NULL
            if (temp->next != NULL)
                temp->next->prev = temp->prev;
            if (temp->prev != NULL)
