```cpp
#include<iostream>
#include<vector>
#include<complex>
#include<math.h>
using namespace std;

typedef complex<double> cd;

cd poly(vector<cd>& xs, cd x) 
{
    cd result = 0;
    for (int i = 0; i < xs.size(); i++)
        result += xs[i] * pow(x, i);

    return result;
}

cd poly_derivative(vector<cd>& xs, cd x) 
{
    cd result = 0;
    for (int i = 1; i < xs.size(); i++) 
        result += xs[i] * i * pow(x, i - 1);

    return result;
}

cd find_zero(vector<cd>& xs, cd initial_guess = 1)
{
    cd root = initial_guess;
    while (abs(poly(xs, root)) > 1e-6)
        root = root - poly(xs, root) / poly_derivative(xs, root);

    return root;
}

int main() 
{
   vector<cd> coefficients = {1, 0, 1}; // x^2 + 1 = 0 has roots i, -i
   std::cout << find_zero(coefficients) << "\n";
   return 0;
}
```

