bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i <= n / 2; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

map<int, int> prime_geometric_series_freq(int n) {
    int primes[] = {2, 3, 5}; // Set of 3 primes
    map<int, int> freq = {{0, 0}, {2, 0}, {3, 0}, {5, 0}, {7, 0}};

    for (int i = 2; i <= n; ++i) {
        bool isDivisibleByAllPrimes = true;
        for (const auto &prime: primes) {
            if (i % prime != 0) {
                isDivisibleByAllPrimes = false;
                break;
            }
        }
        if (isDivisibleByAllPrimes) {
            if (isPrime(i) && i < 10) {
                freq[i]++;
            } else {
                freq[0]++;
            }
        }
    }
    return freq;
}
