```cpp
#include <iostream>
#include <vector>
using namespace std;

vector<pair<int, int>> locate_str(vector<vector<string>> data, string x) {
    vector<pair<int, int>> coords;

    // iterate over the outer vector
    for (size_t row = 0; row < data.size(); row++) {
        // iterate over the inner vector
        for (size_t col = 0; col < data[row].size(); col++) {
            // compare the current element with the target string
            if (data[row][col] == x) {
                coords.push_back({ row, col });
            }
        }
    }
    return coords;
}
```

Here's an example, how to use it:

