    auto locations = locate_str({{"apple","banana"},{"orange","apple","kiwi"},{"apple","grape"}}, "apple");

    for(auto const& pair: locations) {
        cout << "{" << pair.first << ", " << pair.second << "} ";
    }

    return 0;
}
