#include <vector>
#include <sstream>
#include <string>

std::unordered_map<std::string, int> fruit_distribution(std::vector<std::string> s, int n, std::vector<std::string> fruits) {
    // Step 1: Convert the given list of strings into a dictionary
    std::unordered_map<std::string, int> fruit_dict;
    for (auto &i: s) {
        std::istringstream iss(i);
        std::string num, fruit;
        iss >> num >> fruit;
        fruit_dict[fruit] = std::stoi(num);
    }

    // Step 2: Subtract the total number of given fruits from the total number
    int total = 0;
    for (auto iter = fruit_dict.begin(); iter != fruit_dict.end(); ++iter) {
        total += iter->second;
    }
    int remaining_fruits = n - total;

    // Step 3: Distribute the remaining amount equally among the remaining fruits 
    // and add it to the dictionary
    std::vector<std::string> remaining_fruit_list;
    for (auto& fruit : fruits) {
        if (fruit_dict.find(fruit) == fruit_dict.end())
            remaining_fruit_list.push_back(fruit);   
    }

    if (!remaining_fruit_list.empty()) {  
        int distributed_fruits = remaining_fruits / remaining_fruit_list.size();
        for (auto& fruit : remaining_fruit_list)
            fruit_dict[fruit] = distributed_fruits;
    }

    return fruit_dict;
}
```

This version assumes input is same as your Python code in terms of logic. Be aware of that in C++, dividing two integers gives an integer result (this is the same as `//` in Python). If you want to get a real number as result, you need to cast at least one of the integers to a float. If the types of parameters are different, you may need to adjust the code accordingly."}]

