#include <algorithm>
#include <unordered_map>
#include <list>

template <typename T>
T median(std::vector<T> &vec) {
    std::unordered_map<T, int> unique;
    for (const auto &el : vec) {
        unique[el]++;
    }
    std::list<std::pair<T, int>> pairs(unique.begin(), unique.end());
    pairs.sort();
    int length = vec.size();
    // Odd number of elements
    if (length % 2 == 1) {
        int median_index = length / 2;
        int count = 0;
        for (const auto &pair : pairs) {
           count += pair.second;
           if (count > median_index) {
               return pair.first;
           }
        }
    }
    // Even number of elements
    else {
        int median_index = length / 2;
        int count = 0;
        for (typename std::list<std::pair<T, int>>::iterator it = pairs.begin(); it != pairs.end(); ++it) {
            count += it->second;
            if (count == median_index) {
                auto next = std::next(it, 1);
                return (it->first + next->first) / 2.0;
            } else if (count > median_index) {
                return it->first;
            }
        }
    }
    return 0;
}

int main() {
    std::vector<int> v1 = {3, 1, 2, 4, 5};
    std::cout << median(v1) << std::endl;  // Outputs: 3
    std::vector<int> v2 = {-10, 4, 6, 1000, 10, 20};
    std::cout << median(v2) << std::endl;  // Outputs: 15
    std::vector<int> v3 = {1, 2, 2, 4, 5};
    std::cout << median(v3) << std::endl;  // Outputs: 2
    return 0;
}
```

These codes assume that the input vector is nonempty because no error checking is performed before calculating the median."}]

