/*
Given two arrays of positive integers arrays N and M, each containing n elements. 
Return an array of strings of binary representation of the sums of their corresponding elements' digits.

Example:
    If N = [1000, 150, 200] and M = [500, 147, 508], the sums of their corresponding elements' digits are 9, 13, 15
    So, the output should be ["1001", "1101", "1111"].

Variables:
    N and M are arrays of integers with n elements in each array.
         Limit: 0 ≤ n ≤ 1000.
         Limit: 0 ≤ N[i], M[i] ≤ 10^6 for all valid i
Output:
    An array of strings of binary digits
*/

Solution in C++:

```cpp
#include<iostream>
#include<vector>
#include<string>
using namespace std;

string binary_representation(int num){
    string binary = "";
    while(num > 0){
        binary = to_string(num % 2) + binary;
        num /= 2;
    }
    return binary;
}

int sum_of_digits(int num){
    int sum = 0;
    while(num > 0){
        sum += num % 10;
        num /= 10;
    }
    return sum;
}

vector<string> solve(vector<int> N, vector<int> M){
    vector<string> result;
    for(int i=0; i<N.size(); i++){
        int sum = sum_of_digits(N[i]) + sum_of_digits(M[i]);
        result.push_back(binary_representation(sum));
    }
    return result;
}
```"}]

