#include<iostream>
using namespace std;

struct Node {
    int val;
    Node *next, *prev;

    Node(int val) : val(val), next(NULL), prev(NULL) {}
};

class DoublyLinkedList {
public:
    Node *head, *tail;
    DoublyLinkedList() : head(NULL), tail(NULL) {}

    void append(int val) {
        if(head == NULL) {
            head = tail = new Node(val);
        } else {
            Node *node = new Node(val);
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    DoublyLinkedList* merge(DoublyLinkedList* list) {
        if(head == NULL) return list;
        if(list->head == NULL) return this;

        tail->next = list->head;
        list->head->prev = tail;
        tail = list->tail;

        delete list;
        return this;
    }

    void reverse() {
        Node *cur = head, *prevNode = NULL, *nextNode = NULL;

        while(cur != NULL) {
            nextNode = cur->next;
            cur->next = prevNode;
            cur->prev = nextNode;

            prevNode = cur;
            cur = nextNode;
        }

        tail = head;
        head = prevNode;
    }

    void printList() {
        if(head == NULL) return;
        Node* temp=head;
        while(temp)
        {
            cout<<temp->val<<" ";
            temp = temp->next;
        }
        cout<<endl;
    }
};

