        this->y = std::min(std::max(y, min_limit), max_limit);
    }
    void setCoordinates(int new_x, int new_y)
    {
        this->x = std::min(std::max(new_x, min_limit), max_limit);
        this->y = std::min(std::max(new_y, min_limit), max_limit);
    }
    int getX() const { return x; }
    int getY() const { return y; }

    double distanceTo(const Point2D &other) const
    {
        double dx = x - other.x;
        double dy = y - other.y;
        return sqrt(dx * dx + dy * dy);
    }

    bool isOrigin() const
    {
        return x==0 && y==0;
    }   
};
```
In this code, we normalized input values to be in the range [-1000, 1000] in the constructor as well as in `setCoordinates` method using `std::min` and `std::max` functions. 

The `distanceTo` method calculates the Euclidean distance using the formula `sqrt((x2 - x1)^2 + (y2 - y1)^2)`.

The `isOrigin` method simply checks if both `x` and `y` are equal to 0. The `getX`, `getY`, `distanceTo`, `isOrigin` methods are marked as `const` as they do not modify the state of the object and can be called on constant objects."}]

