#include <iostream>
#include <thread>
#include <vector>
#include <mutex>

std::mutex mtx;

int fibonacci(int n) 
{
    int f[n + 2];
    f[0] = 0;
    f[1] = 1;

    for (int i = 2; i <= n; i++) {
      f[i] = f[i - 1] + f[i - 2];
    }

    return f[n];
}

void print_fibonacci(int n, int divisor) 
{ 
    for(int i = 1; i <= n; i++) {
