Area = square root[s(s - a)(s - b)(s - c)],

where a, b, and c represent the sides of the triangle, and s represents the semi-perimeter of the triangle given by s = (a + b + c) / 2.

The steps to check if a triangle is valid are:

- The sum of the lengths of any two sides of a triangle is greater than the length of the third side.

Here is the C++ function:

```cpp
#include <cmath>
#include <iomanip>
#include <iostream>

double triangleArea(double a, double b, double c) {
    // Check if the triangle is valid
    if(a + b <= c || a + c <= b || b + c <= a)
    {
        std::cout << "These sides don't form a valid triangle." << std::endl;
        return -1;
    }

    // Calculate the semi-perimeter
    double s = (a + b + c) / 2;

    // Calculate the area
    double area = std::sqrt(s * (s - a) * (s - b) * (s - c));

    return area;
}

int main() {
    double a = 3.0, b = 4.0, c = 5.0;

    double result = triangleArea(a, b, c);

