```c++
#include <iostream>
#include <random>
#include <vector>
#include <cmath>

bool isPrime(int n) {
    if (n <= 1) {
        return false;
    }

    if (n == 2) {
        return true;
    }

    if (n % 2 == 0) {
        return false;
    }

    for (int i = 3; i <= sqrt(n); i += 2) {
        if (n % i == 0) {
            return false;
        }
    }

    return true;
}

std::vector<int> primeFactors(int n) {
    std::vector<int> factors;
    for (int i = 2; i <= n; i++) {
        while (n % i == 0) {
            factors.push_back(i);
            n /= i;
        }
    }
    return factors;
}

int generateRandomPrime(int min, int max) {
    std::random_device rd;
    std::mt19937 mt(rd());
    std::uniform_int_distribution<int> dist(min, max);

    int num = dist(mt);

    while (true) {
        if (isPrime(num)) {
            std::vector<int> factors = primeFactors(num);
            std::vector<int> distinctFactors;

            for (int factor : factors) {
                if (std::find(distinctFactors.begin(), distinctFactors.end(), factor) == distinctFactors.end()) {
                    distinctFactors.push_back(factor);
                }
            }

            if (distinctFactors.size() >= 3) {
                break;
            }
        }

        num = dist(mt);
    }

    return num;
}

int main() {
    int prime = generateRandomPrime(10000, 100000);
    std::cout << "Random Prime: " << prime << std::endl;

    return 0;
}
