```cpp
#include <iostream>

// Recursive bubble sort function
void bubbleSortRecursive(int arr[], int n)
{
    // Base case
    if (n == 1)
        return;

    // One pass of bubble sort, moves the largest element to end
    for (int i = 0; i < n - 1; i++) {
        if (arr[i] > arr[i + 1])
            std::swap(arr[i], arr[i + 1]);
    }

    // Recursive call for remaining elements
    bubbleSortRecursive(arr, n - 1);
}

int main()
{
    int n;
    std::cout << "Enter the number of elements: ";
    std::cin >> n;

    int arr[10000];
    std::cout << "Enter the elements:\n";
    for (int i = 0; i < n; i++)
        std::cin >> arr[i];

    // Sorting the array using recursive bubble sort
    bubbleSortRecursive(arr, n);

    std::cout << "Sorted array: ";
    for (int i = 0; i < n; i++)
        std::cout << arr[i] << " ";
    std::cout << std::endl;

    return 0;
}
```

