void reverseString(std::string& str) {
    int left = 0, right = str.length() - 1;

    while (left < right) {
        // Ignore whitespace characters
        while (left < right && !isalnum(str[left])) {
            left++;
        }
        while (left < right && !isalnum(str[right])) {
            right--;
        }

