    for (int i = 0; i < THREAD_COUNT; i++) {
        int start = i * chunkSize + 1;
        int end = (i == THREAD_COUNT - 1) ? NUM_RANGE : (i + 1) * chunkSize;
        threads.push_back(std::thread(findPrimes, start, end));
    }

    // Join threads
    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
