struct BudgetItem {
    int cost;
    std::string description;
};

int calculateMaxBudgetItems(const std::vector<BudgetItem>& budgetItems, int maxCost) {
    int n = budgetItems.size();
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(maxCost + 1, 0));

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= maxCost; j++) {
            if (budgetItems[i - 1].cost <= j) {
                dp[i][j] = std::max(dp[i - 1][j], dp[i - 1][j - budgetItems[i - 1].cost] + 1);
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    return dp[n][maxCost];
}

int main() {
    int maxCost = 500;
    std::vector<BudgetItem> budgetItems = {
        {100, "PrintBook"},
        {250, "EditBook"},
        {400, "DesignBook"},
        {150, "PromoteBook"},
        {200, "PublishBook"}
    };

    int maxBudgetItems = calculateMaxBudgetItems(budgetItems, maxCost);
    std::cout << "Maximum number of budget items within the constraint: " << maxBudgetItems << std::endl;

    return 0;
}"}]

