    // Base case: if one of the numbers is 0, return the other number
    if (a == 0) return b;
    if (b == 0) return a;

    // Recursive case: call the function with the remainder of a divided by b
    return gcd(b, a % b);
}

// Function to check if two numbers are co-prime or not
bool isCoPrime(long long int a, long long int b) {
