[{"role": "assistant", "content": "#include <iostream>
using namespace std;

class Stack {
private:
  int *arr; // Dynamic array to store stack elements
  int top; // Index of top element
  int capacity; // Maximum capacity of the stack

public:
  // Constructor to initialize an empty stack
  Stack(int size) {
    arr = new int[size];
    capacity = size;
    top = -1;
  }

  // Destructor to deallocate memory
  ~Stack() {
    delete[] arr;
  }

  // Method to check if the stack is empty
  bool isEmpty() {
    return top == -1;
  }

  // Method to check if the stack is full
  bool isFull() {
    return top == capacity - 1;
  }

  // Method to push an element onto the stack
  void push(int element) {
    if (isFull()) {
      cout << "Stack Overflow\n";
      return;
    }
    arr[++top] = element;
    cout << "Element " << element << " pushed to stack\n";
  }

  // Method to pop an element from the stack
  int pop() {
    if (isEmpty()) {
      cout << "Stack Underflow\n";
      return -1;
    }
    return arr[top--];
  }

  // Method to retrieve the top element of the stack without removing it
  int peek() {
    if (isEmpty()) {
      cout << "Stack is empty\n";
      return -1;
    }
    return arr[top];
  }

  // Method to clear the stack
  void clear() {
    top = -1;
    cout << "Stack cleared\n";
  }

  // Method to get the size of the stack
  int size() {
    return top + 1;
  }

  // Method to print the elements of the stack in reverse order
  void printReverse() {
    if (isEmpty()) {
      cout << "Stack is empty\n";
      return;
    }
    cout << "Elements in reverse order: ";
    for (int i = top; i >= 0; i--) {
      cout << arr[i] << " ";
    }
    cout << endl;
  }
};

int main() {
  Stack stack(5); // Creating a stack of capacity 5

  stack.push(1);
  stack.push(2);
  stack.push(3);
  stack.push(4);
  stack.push(5);

  stack.push(6); // Stack Overflow

  cout << "Size of stack: " << stack.size() << endl; // Size of stack: 5

  cout << "Top element of stack: " << stack.peek() << endl; // Top element of stack: 5

  stack.printReverse(); // Elements in reverse order: 5 4 3 2 1

  cout << "Popped element: " << stack.pop() << endl; // Popped element: 5

  stack.clear(); // Stack cleared

  cout << "Is stack empty? " << (stack.isEmpty() ? "Yes" : "No") << endl; // Is stack empty? Yes

  return 0;
}"}]

